"""Produce the user-facing technical report and experimental inventory."""
from pathlib import Path
import json,csv,shutil,math,hashlib,time
REPO=Path(__file__).resolve().parents[3];OUT=REPO/'reports/v5/hybrid/experiments-2026-10-30';DELIVER=Path('/home/sebas/Documents/Codex/2026-10-26/ta/outputs/Metricas_Firewall_2026-10-30')
def percent(x):return 'N/D' if x is None else f'{100*x:.2f}%'
def ms(x):return 'N/D' if x is None else f'{x:.2f} ms'
def main():
    s=json.loads((OUT/'summary.json').read_text());DELIVER.mkdir(parents=True,exist_ok=True);lines=[]
    def add(text=''):lines.append(text)
    add('# Firewall-IA: métricas experimentales de modelos y cascada')
    add('\nFecha: 30 de octubre de 2026. Rama `feat/hybrid-cascade-integration`.\n')
    add('**Resultado:** ambos modelos y la cascada funcionan en el laboratorio HTTP/1.1 y ya tienen evidencia experimental reproducible. Esto no acredita despliegue ni evaluación final: persisten la selección/calibración de la política, el objetivo de latencia y los conjuntos reservados. No se entrenó, no se hizo staging/commit/push y no se abrió PR.\n')
    add('## 1. Qué se ejecutó\n')
    add('- 1.034 peticiones de desarrollo: 600 del conjunto anterior y 434 casos del diagnóstico emparejado del proyecto. Veintidós solicitudes del conjunto anterior fallan el parser de protocolo; quedan 578 + 434 = 1.012 entradas comunes para comparar V4, V5 y Model 2.')
    add('- V4 recibe el render D1 del gateway real; V5 recibe el texto canónico; Model 2 recibe sus features C1. Se preserva la petición de origen común. No se mandó a V4 el texto de V5 ni se confundieron las arquitecturas.')
    add('- Tres procesos nuevos por LLM; cada uno separa una primera inferencia fría, cuatro calentamientos y 96 peticiones de benchmark en el mismo orden. Batch 1 y concurrencia 1. Sincronización CUDA en los núcleos originales. Percentiles por rango más próximo, sin eliminar atípicos.')
    add('- Repetibilidad: 58 textos fijos, tres salidas por texto y LLM, comparadas por hash del texto generado. Diagnóstico de desarrollo, no gate STAB.')
    add('- Tres pasadas reales por gateway, 600 peticiones cada una: V5_ONLY, cascada baseline34 y cascada path-ablation32. Destino controlado independiente; hashes de bytes recibidos. Cuatro calentamientos del servicio excluidos.')
    add('- Carga de API: 48 solicitudes por nivel de concurrencia 1/4/8/16. Carga del gateway completo: 48 por modo y concurrencia 1/4/16, con el mismo tráfico sintético mixto. No son pruebas de capacidad sostenida.')
    add('- Guardas de Fast Path, latencia de 64 permisos sintéticos por candidato, fallos controlados, recuperación tras carga y comprobación adicional de las cinco rutas reales.\n')
    add('Los conjuntos reservados INTERNAL_TEST, STAB-HELD y externos no se abrieron. El umbral 0,9 y la política Fast Path siguen siendo experimentales; no se ajustaron pesos, calibradores ni umbrales con estas mediciones.\n')
    add('## 2. Calidad: decisiones de seguridad, no solamente accuracy\n')
    add('Clase positiva = BLOCK. E5 cuenta cada salida inválida como error de su clase real; también se informa la vista de salidas válidas y se separan rechazos del límite de contenido.\n')
    add('| Población | Sistema | TP | TN | FP | FN | Precision BLOCK | Recall BLOCK | FPR benignos | F1 |')
    add('|---|---|---:|---:|---:|---:|---:|---:|---:|---:|')
    for cohort,label in [('legacy_dev','Anterior DEV'),('authored_paired_dev','Diagnóstico DEV')]:
        points=[('V4',s['quality']['v4'][cohort]['principal']),('V5',s['quality']['v5'][cohort]['principal'])]
        if cohort=='legacy_dev':points += [(n+' (gateway real)',s['gateway'][n]['L1_semantic_E5']['principal']) for n in ('baseline34','path-ablation32')]
        else:points += [(n+' (derivada)',s['counterfactual_cascade'][n][cohort]['quality_E5']['principal']) for n in ('baseline34','path-ablation32')]
        for name,p in points:add(f'| {label} | {name} | {p["TP"]} | {p["TN"]} | {p["FP"]} | {p["FN"]} | {percent(p["precision_block"])} | {percent(p["recall_block"])} | {percent(p["fpr"])} | {p["f1_block"]:.4f} |')
    add('\nV5 elimina los 68 falsos bloqueos que V4 produce en los 221 benignos del diagnóstico del proyecto. Sin embargo, detecta 172/213 ataques frente a 206/213 de V4: mejorar benignos no equivale a mantener toda la detección. El denominador y la familia importan. Cero errores observados tampoco prueba un riesgo real igual a cero.\n')
    q=s['quality']['v5']['legacy_dev'];inside=q['in_vocabulary_binary']['principal'];outside=q['outside_vocabulary_attacks']['principal']
    add(f'En el conjunto anterior, la vista binaria de las categorías de salida cubiertas por V5 tiene recall {percent(inside["recall_block"])} ({inside["TP"]}/{inside["TP"]+inside["FN"]}); en ataques fuera de ese vocabulario, {percent(outside["recall_block"])} ({outside["TP"]}/{outside["TP"]+outside["FN"]}). Son observaciones DEV, no recall validado de las categorías TRAIN-only. Las razones se puntúan solo en ataques correctamente bloqueados y con una correspondencia definida.\n')
    add('Las peticiones anteriores se transformaron en wire HTTP y se renderizaron por D1, incluyendo Content-Length cuando corresponde. Por eso las cifras de V4 aquí no sustituyen ni contradicen automáticamente su evaluación histórica: cambia la población/representación de prueba. La comparación válida es la emparejada dentro de este experimento.\n')
    add('También se entregan accuracy, balanced accuracy, specificity, NPV, MCC, F1 macro, F2, FNR, matrices, errores de parseo/EOS, rechazos sin generación, motivos exactos, cortes por familia/carrier y pares ataque/benigno. Los intervalos Wilson y McNemar son diagnósticos nominales bajo independencia; las dependencias impiden tratarlos como garantía poblacional.\n')
    add('## 3. Model 2: evaluación selectiva y probabilística\n')
    add('| Candidato / población | Ataques bloqueados temprano | Benignos bloqueados temprano | Precision temprana | DEFER | ROC-AUC | AP | Brier | ECE |')
    add('|---|---:|---:|---:|---:|---:|---:|---:|---:|')
    for name,data in s['model2'].items():
        for cohort,q in data['cohorts'].items():
            p=q['probability_metrics']['probability_diagnostics'];add(f'| {name} / {cohort} | {q["early_block_TP"]}/{q["attack_N"]} | {q["early_block_FP"]}/{q["benign_N"]} | {percent(q["early_block_precision"])} | {percent(q["defer_rate"])} | {p["roc_auc"]:.4f} | {p["pr_auc"]:.4f} | {p["brier"]:.4f} | {p["ece"]:.4f} |')
    add('\nSe entregan log-loss, reliability con 15 bins, curvas ROC/PR, siete umbrales descriptivos y ponderación por grupos de vectores idénticos. DEFER significa derivar al LLM y no se etiqueta como un falso negativo del decider. El corte 0,5 de algunas tablas es una convención binaria de diagnóstico; no crea una ruta ALLOW ni cambia el umbral activo del laboratorio.\n')
    o=s['TRAIN_overlap']
    for view in ('baseline_34','target-path-neutralized/v1'):
        for cohort,d in o[view].items():add(f'- Coincidencias con TRAIN, {view} / {cohort}: texto canónico {len(d["canonical_text_overlap_ids"])}/{d["N"]}; vector exacto {len(d["feature_vector_overlap_ids"])}/{d["N"]}.')
    add('\nLa vista sin path tiene más colisiones de features. Se entregan resultados sobre la vista disjunta de TRAIN y sobre grupos de vectores; ninguna de estas vistas demuestra independencia de familias o fuentes. La ablación retira solo path_length/path_depth, no toda información indirecta del path. No se declara ganador operativo.\n')
    add('## 4. Cascada: qué evita y qué entrega realmente\n')
    add('| Modo | Llamadas reales a V5 | Llamadas evitadas / 578 | Falsos bloqueos semánticos | Ataques entregados al destino | Desacuerdos L2 | Bytes alterados |')
    add('|---|---:|---:|---:|---:|---:|---:|')
    for name,g in s['gateway'].items():add(f'| {name} | {g["actual_V5_calls"]} | {g["actual_calls_avoided_vs_v5_only_eligible"]} ({percent(g["actual_call_avoidance_fraction_eligible"])}) | {g["L1_semantic_E5"]["principal"]["FP"]} | {g["attack_forwarded_eligible"]} | {g["L2_enforcement_mismatch_N"]} | {g["forwarded_wire_hash_mismatch_N"]} |')
    add('\nL1 compara referencia y decisión; L2 compara acción, estado HTTP y recepción independiente; L3 compara referencia y entrega real. Los inválidos son errores en L1 aunque el bloqueo preventivo reduzca ataques entregados en L3. La entrega a un servidor inerte no demuestra explotación ni compromiso. Bajo concurrencia se compara la recepción agregada por hash, sin inventar correspondencias individuales entre solicitudes repetidas.\n')
    add('En estas 600 solicitudes ninguna cumple la política positiva Fast Path; su cobertura no se inventa. Sus rutas positivas y negativas se miden por separado con entradas sintéticas. El ahorro de llamadas ahora sí procede de ejecuciones reales, mientras que las cascadas del diagnóstico emparejado siguen marcadas como derivadas.\n')
    add('## 5. Latencia, carga y recursos\n')
    add('D36 exige P95 ≤ 200 ms del pipeline de inferencia estable. No es solo generación ni tiempo total por HTTP.\n')
    add('| Modelo | P95 pipeline, ejecución 1 | Ejecución 2 | Ejecución 3 | P95 agrupado | Pico VRAM asignada |')
    add('|---|---:|---:|---:|---:|---:|')
    for name,b in s['benchmarks'].items():
        rss=max(r['memory']['cuda_peak_allocated_bytes'] for r in b['runs'])/1024**2;add(f'| {name.upper()} | {ms(b["runs"][0]["pipeline_ms"]["p95"])} | {ms(b["runs"][1]["pipeline_ms"]["p95"])} | {ms(b["runs"][2]["pipeline_ms"]["p95"])} | {ms(b["pooled_pipeline_ms"]["p95"])} | {rss:.1f} MiB |')
    add('\n**D36 no se cumple en las ejecuciones medidas.** La comparación es de los stacks nativos, con sus respectivas plantillas y cuantización; no es una ablación que aísle el efecto de los pesos. Evitar llamadas reduce trabajo, pero no hace que la inferencia restante cumpla 200 ms.\n')
    add('| API: clientes concurrentes | Respuestas/s | Clasificaciones válidas/s | 503 | P95 cliente (todas) | P95 espera GPU (válidas) |')
    add('|---|---:|---:|---:|---:|---:|')
    for concurrency,d in s['load'].items():add(f'| {concurrency} | {d["throughput_responses_per_s"]:.2f} | {d["goodput_valid_classifications_per_s"]:.2f} | {percent(d["saturation_rate"])} | {ms(d["latency_all_ms"]["p95"])} | {ms(d["queue_wait_ms_valid"]["p95"])} |')
    add('\nLa API y el gateway completo tienen tablas separadas. Se registran latencias de todas las respuestas, válidas y errores; cola, clasificación, throughput y goodput; rutas, saturación y recuperación. Un 403 por indisponibilidad no cuenta como clasificación autorizada en el goodput del gateway. Con 48 solicitudes por nivel, P99 es una observación extrema con mucha incertidumbre; no acredita un SLO ni carga sostenida. El gateway local usa ThreadingTCPServer, no un servidor de producción optimizado.\n')
    add('Se incluyen carga del modelo, primera inferencia fría, calentamientos, tiempos de etapas, tokens, tokens/s de generación, RSS, VRAM asignada/reservada y muestras de temperatura, utilización, potencia y reloj de la GPU. La VRAM total de nvidia-smi incluye procesos ajenos; las muestras de potencia no equivalen a energía causal ni permiten afirmar CO₂ o coste energético por solicitud.\n')
    add('## 6. Verificación de mecanismos\n')
    add('- 72/72 pruebas unitarias afectadas; incluye la regresión de un CRLF de chunk repartido entre recepciones. Se distingue mensaje incompleto de terminador realmente mal formado.')
    add('- Verificación real adicional: 18 comprobaciones sobre las cinco rutas del laboratorio, con pesos reales. Registro en real_routes.log.')
    for name,d in s['determinism'].items():add(f'- {name.upper()}: {d["texts"]} textos × {d["outputs_per_text"]} salidas; divergencias por hash: {len(d["byte_hash_divergences"])}.')
    add(f'- Fallos controlados superados: {sum(r["passed"] for r in s["failure_controls"])}/{len(s["failure_controls"])}. Excepción de Model 2 y respuesta no-OK+BLOCK derivan a V5; V5 no disponible o inválido bloquea. Los fallos inyectados están identificados como tales. Recuperación tras carga: {s["post_load_recovery"]["status"]}.')
    add('- El servicio temporal se detiene al acabar. Adaptadores, hashes del código, datasets, entorno, protocolo, selección/orden, registros y cálculos quedan vinculados en los manifiestos.\n')
    add('## 7. Qué falta para una conclusión final del proyecto\n')
    add('1. Fijar un presupuesto de falsos bloqueos y elegir/calibrar la política de Model 2 en VALIDATION adecuada e independiente. La validación original tiene 40 filas y un componente: no permite prometer tasas raras con precisión. No usar INTERNAL_TEST para resolverlo.')
    add('2. Resolver o aceptar explícitamente la pérdida de recall por familia y el incumplimiento de D36. Usar los diagnósticos DEV para el trabajo de ingeniería; cualquier versión nueva requiere conservar su propia identidad y protocolo.')
    add('3. Congelar modelo/candidato, umbral, política, representación y protocolo; ejecutar una sola evaluación final conjunta autorizada de INTERNAL_TEST, STAB-HELD D77 G1–G5 y evaluación externa correspondiente, sin selección ni depuración sobre esos resultados.')
    add('4. Medir la integración de despliegue pendiente: delta mitmproxy D70, HTTP/2/TLS si están en alcance, auditoría asíncrona de FAST_ALLOW, observabilidad y pruebas sostenidas de recuperación/carga. C2 sigue opcional y ausente; no se le atribuyen métricas.')
    add('\nG1/G2 requieren los controles y contrastes registrados, C_hi propio y la interpretación ratificada de D77. G3/G4 requieren la población protegida correspondiente; los cortes por benignos/carrier de este experimento solo son diagnósticos. Las 58 repeticiones DEV tampoco acreditan G5. No se sustituyeron estos gates por muestras más cómodas.\n')
    add('Para planificar una tasa rara: con cero errores y observaciones Bernoulli realmente independientes, el límite superior unilateral exacto al 95% es `1 - 0.05^(1/n)`. Harían falta al menos 2.995 benignos sin errores para bajar de 0,1%, y 29.956 para bajar de 0,01%. Son ejemplos teóricos, no garantías aplicables a estos datos dependientes ni presupuestos operativos inventados.\n')
    add('## 8. Archivos y reproducción\n')
    add('Tablas: quality.csv, slices.csv, stability_dev_by_carrier.csv, model2_probability.csv, model2_thresholds_descriptive.csv, latency.csv y metric_inventory.csv. Datos estructurados completos: summary.json. Los JSONL incluyen decisiones, hashes y tiempos, nunca peticiones privadas. Los inputs derivados de terceros quedan fuera del repositorio, con hash y receta de reconstrucción.\n')
    add('El protocolo congelado vive en protocol.json; supplemental_protocol.json declara el ensayo sintético de carga antes de ejecutarlo. executed_sources conserva los tres programas de medición ejecutados. measurement_source_hashes.json identifica el código real; evidence_manifest.json y code_manifest.json permiten verificar el conjunto final.\n')
    add('Las etapas de análisis se vuelven a ejecutar sin GPU ni modelos: `analyze.py`, `figures.py`, `report.py`. Para repetir mediciones hay que usar un directorio nuevo y reconstruir los inputs con prepare.py; no sobreescribir esta evidencia. No ejecutar entrenamiento para reproducir estas métricas.\n')
    add('## Gráficas\n')
    for title,name in [('Calidad y falsos bloqueos','quality_tradeoffs'),('Latencia de los stacks nativos','native_latency_ecdf'),('Discriminación y calibración de Model 2','model2_probability_diagnostics'),('Carga de API','api_load'),('Carga de la cascada completa','gateway_load'),('Rutas y llamadas reales a V5','routes_and_actual_calls')]:add(f'### {title}\n\n![{title}]({DELIVER}/figures/{name}.png)\n')
    text='\n'.join(lines)+'\n';(OUT/'INFORME.md').write_text(text)
    (OUT/'README.md').write_text('# Experimental DEV metrics — 2026-10-30\n\nSee INFORME.md and summary.json. No protected evaluation or deployment approval. No training, staging, commits, push or PR. Third-party raw inputs remain outside Git.\n')
    # Carrier table is a DEV G4-like diagnostic, never a protected gate.
    v4={r['id']:r for r in map(json.loads,(OUT/'v4_quality.jsonl').read_text().splitlines())};v5={r['id']:r for r in map(json.loads,(OUT/'v5_quality.jsonl').read_text().splitlines())};carriers=sorted({r['placement'] for r in v4.values() if r['cohort']=='authored_paired_dev'});table=[]
    for carrier in carriers:
        rs=[r for r in v4.values() if r['cohort']=='authored_paired_dev' and r['placement']==carrier];att=[r for r in rs if r['label']=='BLOCK'];ben=[r for r in rs if r['label']=='ALLOW'];rec4=sum(r['decision']=='BLOCK' for r in att)/len(att) if att else None;rec5=sum(v5[r['id']]['decision']=='BLOCK' for r in att)/len(att) if att else None
        table.append(dict(carrier=carrier,attack_N=len(att),benign_N=len(ben),v4_attack_recall=rec4,v5_attack_recall=rec5,delta_recall_pp=100*(rec5-rec4) if att else None,v4_false_blocks=sum(r['decision']=='BLOCK' for r in ben),v5_false_blocks=sum(v5[r['id']]['decision']=='BLOCK' for r in ben),scope='DEV diagnostic only; not D77 G3/G4'))
    with (OUT/'stability_dev_by_carrier.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(table[0]));w.writeheader();w.writerows(table)
    inventory=[('Binary quality / D19 E5','MEASURED + DERIVED','V4/V5, both DEV cohorts; invalids as errors'),('Reason exact / taxonomy','MEASURED + DERIVED','Correctly blocked mapped cases only'),('Model2 ROC/PR/AP/Brier/logloss/ECE','MEASURED + DERIVED','Both candidates; no post-hoc calibration fit'),('Model2 selective BLOCK/DEFER','MEASURED + DERIVED','Lab .9; no serving ALLOW'),('Group-weighted / TRAIN feature-disjoint','DERIVED DIAGNOSTIC','TRAIN only; exact feature groups are not independent source families'),('D31 generation / D32 repeats','MEASURED','Three fresh native model processes; fixed same 96 IDs/order'),('D36 native pipeline p95','MEASURED; OBJECTIVE NOT MET','Target 200 ms; neither HTTP nor queue mixed into inference'),('Gateway L1/L2/L3','MEASURED + DERIVED','600 wires per mode; independent exact-wire sink evidence'),('Actual V5 API-call avoidance','MEASURED','Three real gateway modes, not solely counterfactual'),('Authored paired cascade','DERIVED COUNTERFACTUAL','Both real standalone outputs; no additional socket pass'),('Fast Path guard / latency','MEASURED SYNTHETIC','Positive routes and near-neighbor guards; no production coverage claim'),('API load / saturation / recovery','MEASURED SYNTHETIC','48 per level, one benign text; closed loop'),('Whole gateway load','MEASURED SYNTHETIC','48 per mode/level; identical fixed three-route mix'),('Resources / thermal / model load','MEASURED','Torch VRAM/RSS and 1Hz device telemetry; live process samples'),('Failure handling','TESTED; INJECTED FAILURES TAGGED','Model2 DEFER, V5 fail-closed, post-load recovery'),('D77 G1/G2 controls and high contrasts','NOT RUN PROTECTED','Requires registered STAB held set + frozen final protocol'),('D77 G3/G4','NOT RUN PROTECTED','DEV benign and carrier tables supplied separately'),('D77 G5','NOT RUN PROTECTED','58x3 DEV repeats supplied separately'),('INTERNAL_TEST / final Model2 evaluation','NOT RUN PROTECTED','Freeze operational candidate, threshold and joint one-look protocol first'),('External/E6/generalization','NOT RUN PROTECTED','Independent authorized data and final locked system required'),('Population rare FPR / risk CI','NOT ESTIMABLE','Small dependent DEV sample; nominal IID diagnostics labelled'),('Exploit success / stateful bypass','NOT ESTIMABLE','Inert sink measures delivery, not compromise'),('HTTP2/TLS/mitmproxy D70','NOT TESTED','Current integration is an isolated HTTP1 lab'),('C2 / async fast-path audit','NOT IMPLEMENTED','C2 optional; absent stages never receive fabricated metrics'),('Energy/CO2/causal inference cost','NOT ESTIMABLE','Device power snapshots are not an energy experiment')]
    with (OUT/'metric_inventory.csv').open('w',newline='') as f:w=csv.writer(f);w.writerow(['metric_family','status','scope_or_requirement']);w.writerows(inventory)
    for p in OUT.iterdir():
        if p.is_file() and (p.suffix in ('.csv','.json','.md') or p.name=='real_routes.log'):shutil.copy2(p,DELIVER/p.name)
    shutil.copytree(OUT/'figures',DELIVER/'figures',dirs_exist_ok=True)
    print(DELIVER/'INFORME.md')
if __name__=='__main__':main()
